<div x-data="roomPreview(@js($field['previews']), @js($field['value']))"><select id="{{ $inputId }}" name="room_id" class="app-input" x-model="selected" @change="fill()" required><option value="">Chọn phòng</option>@foreach($field['options'] as $key=>$label)<option value="{{ $key }}">{{ $label }}</option>@endforeach</select><template x-if="room"><div class="mt-4 rounded-xl border border-slate-200 p-4 dark:border-slate-700"><div class="flex items-start gap-3"><img :src="room.image" alt="Ảnh phòng đã chọn" class="h-20 w-24 shrink-0 rounded-lg object-cover"><div class="min-w-0 text-sm"><h3 class="font-bold" x-text="room.property + ' · ' + room.name"></h3><p class="mt-2" x-text="room.area + ' m² · Tối đa ' + room.capacity + ' người'"></p><p class="mt-2" x-text="room.rent + '/tháng · Cọc ' + room.deposit"></p></div></div><p class="mt-3 text-sm text-slate-500" x-text="room.amenities || 'Chưa cập nhật tiện nghi'"></p><p class="mt-3 text-xs leading-5 text-slate-500">Thông số và hình phòng được dùng cho tin khi bạn chưa chọn bộ ảnh riêng.</p></div></template></div>
